structureCode.vanilla:
const paleta = createCommand({
  placeholder: 'Buscar...',
  emptyMessage: 'Nenhum resultado.',
  // O agrupamento vem do campo `group`; a factory desenha o traço entre um
  // grupo e o seguinte. `{ type: 'separator' }` quebra a sequência onde não há
  // grupo nenhum a separar.
  items: [
    { value: 'item',  label: 'Rótulo do item', group: 'Grupo',       shortcut: 'Ctrl+K' },
    { value: 'outro', label: 'Outro item',     group: 'Outro grupo' },
    { type: 'separator' },
    { value: 'sair',  label: 'Sair' },
  ],
  onSelect: (valor) => console.log(valor),
});

